function New-CustomAppProductionEvidenceBoundJournalAtomicDeniedV010 {
    param([Parameter(Mandatory=$true)][string]$Reason,[AllowNull()][string]$TransactionRoot=$null,[AllowNull()][string]$JournalPhase=$null,[bool]$LiveMoveStarted=$false,[bool]$EvidencePersisted=$false)
    return [pscustomobject]@{
        ok=$false;reason=$Reason;result=$null;transaction_root=$TransactionRoot;journal_phase=$JournalPhase;live_move_started=$LiveMoveStarted;recovery_evidence_persisted=$EvidencePersisted
        recovery_evidence_bound_before_atomic_barrier=$false;result_is_authority=$false;requires_recovery=($LiveMoveStarted -or -not [string]::IsNullOrWhiteSpace($JournalPhase))
        spicetify_apply_authorized=$false;additional_mutation_authorized=$false;production_execution_authorized=$false;production_mutation_authorized=$false
    }
}
function Get-CustomAppProductionEvidenceBoundJournalAtomicSha256V010 {
    param([AllowNull()][string]$Text)
    if($null -eq $Text){$Text=''}
    $sha=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($Text))).Replace('-','').ToLowerInvariant())}finally{$sha.Dispose()}
}
function Get-CustomAppProductionEvidenceBoundJournalAtomicResultMaterialV010 {
    param([Parameter(Mandatory=$true)]$Result)
    return @(
        [string]$Result.schema,[string]$Result.managed_by,[string]$Result.qualified_journal_aware_head,[string]$Result.qualified_journal_aware_core_blob,[string]$Result.qualified_recovery_evidence_head,[string]$Result.qualified_recovery_evidence_core_blob,
        [string]$Result.name,[string]$Result.transaction_id,[string]$Result.transaction_root,[string]$Result.old_live_path,[string]$Result.live_path,[string]$Result.stage_path,
        [string]$Result.pre_live_full_tree_sha256,[string]$Result.post_runtime_tree_sha256,[string]$Result.persistence_fingerprint,[string]$Result.journal_revision,[string]$Result.journal_entry_sha256,
        [string]$Result.recovery_evidence_fingerprint,[string]$Result.recovery_evidence_path,[string]$Result.recovery_evidence_persisted,[string]$Result.recovery_evidence_bound_before_atomic_barrier,
        [string]$Result.live_code_swap_performed,[string]$Result.requires_transaction_finalization,[string]$Result.requires_spicetify_apply_phase,
        [string]$Result.result_is_authority,[string]$Result.spicetify_apply_authorized,[string]$Result.additional_mutation_authorized,[string]$Result.production_execution_authorized,[string]$Result.production_mutation_authorized
    ) -join "`n"
}
function Test-CustomAppProductionEvidenceBoundJournalAtomicResultV010 {
    param([AllowNull()]$Result)
    if($null -eq $Result){return [pscustomobject]@{ok=$false;reason='evidence-bound-atomic-result-null'}}
    foreach($f in @('schema','managed_by','qualified_journal_aware_head','qualified_journal_aware_core_blob','qualified_recovery_evidence_head','qualified_recovery_evidence_core_blob','name','transaction_id','transaction_root','old_live_path','live_path','stage_path','pre_live_full_tree_sha256','post_runtime_tree_sha256','persistence_fingerprint','journal_revision','journal_entry_sha256','recovery_evidence_fingerprint','recovery_evidence_path','recovery_evidence_persisted','recovery_evidence_bound_before_atomic_barrier','live_code_swap_performed','requires_transaction_finalization','requires_spicetify_apply_phase','result_is_authority','spicetify_apply_authorized','additional_mutation_authorized','production_execution_authorized','production_mutation_authorized','result_fingerprint')){if(-not $Result.PSObject.Properties[$f]){return [pscustomobject]@{ok=$false;reason=('evidence-bound-atomic-result-field-missing-'+$f)}}}
    if([int]$Result.schema -ne 1 -or [string]$Result.managed_by -cne $CustomAppProductionEvidenceBoundJournalAtomicManagedBy -or [string]$Result.qualified_journal_aware_head -cne $CustomAppProductionEvidenceBoundJournalAtomicQualifiedJournalAwareHead -or [string]$Result.qualified_journal_aware_core_blob -cne $CustomAppProductionEvidenceBoundJournalAtomicQualifiedJournalAwareCoreBlob -or [string]$Result.qualified_recovery_evidence_head -cne $CustomAppProductionEvidenceBoundJournalAtomicQualifiedEvidenceHead -or [string]$Result.qualified_recovery_evidence_core_blob -cne $CustomAppProductionEvidenceBoundJournalAtomicQualifiedEvidenceCoreBlob){return [pscustomobject]@{ok=$false;reason='evidence-bound-atomic-result-lineage-invalid'}}
    foreach($f in @('transaction_id','pre_live_full_tree_sha256','post_runtime_tree_sha256','persistence_fingerprint','journal_entry_sha256','recovery_evidence_fingerprint','result_fingerprint')){if(([string]$Result.$f).Trim().ToLowerInvariant() -notmatch '^[0-9a-f]{64}$'){return [pscustomobject]@{ok=$false;reason=('evidence-bound-atomic-result-sha-invalid-'+$f)}}}
    foreach($f in @('recovery_evidence_persisted','recovery_evidence_bound_before_atomic_barrier','live_code_swap_performed','requires_transaction_finalization','requires_spicetify_apply_phase')){if(-not [bool]$Result.$f){return [pscustomobject]@{ok=$false;reason=('evidence-bound-atomic-result-required-flag-false-'+$f)}}}
    foreach($f in @('result_is_authority','spicetify_apply_authorized','additional_mutation_authorized','production_execution_authorized','production_mutation_authorized')){if([bool]$Result.$f){return [pscustomobject]@{ok=$false;reason=('evidence-bound-atomic-result-authority-escaped-'+$f)}}}
    if([int64]$Result.journal_revision -lt 3){return [pscustomobject]@{ok=$false;reason='evidence-bound-atomic-result-journal-revision-too-low'}}
    $expected=Get-CustomAppProductionEvidenceBoundJournalAtomicSha256V010 (Get-CustomAppProductionEvidenceBoundJournalAtomicResultMaterialV010 -Result $Result)
    if(([string]$Result.result_fingerprint).Trim().ToLowerInvariant() -cne $expected){return [pscustomobject]@{ok=$false;reason='evidence-bound-atomic-result-fingerprint-mismatch'}}
    return [pscustomobject]@{ok=$true;reason='evidence-bound-journal-atomic-result-valid-zero-authority';result_fingerprint=$expected;production_mutation_authorized=$false}
}
function Test-CustomAppProductionEvidenceBoundJournalAtomicPreparedContinuityV010 {
    param([Parameter(Mandatory=$true)]$PreparedResult,[Parameter(Mandatory=$true)][string]$Name,[Parameter(Mandatory=$true)][string]$ConsumptionId,[Parameter(Mandatory=$true)][string]$SourceIdentity,[Parameter(Mandatory=$true)][string]$RemoteCommitSha,[Parameter(Mandatory=$true)][string]$StageResultFingerprint,[Parameter(Mandatory=$true)][string]$PreparationFingerprint,[Parameter(Mandatory=$true)][string]$StageWorkspacePath,[Parameter(Mandatory=$true)][string]$StagePath,[Parameter(Mandatory=$true)][string]$ExpectedLiveRuntimeTreeSha256,[Parameter(Mandatory=$true)][string]$ExpectedStageRuntimeTreeSha256,[Parameter(Mandatory=$true)][string]$AppBackupPath,[Parameter(Mandatory=$true)][string]$ExpectedAppBackupTreeSha256,[Parameter(Mandatory=$true)][int]$ExpectedAppBackupFileCount,[Parameter(Mandatory=$true)][int64]$ExpectedAppBackupTotalBytes,[Parameter(Mandatory=$true)][string]$PersistenceBackupPath,[Parameter(Mandatory=$true)][string]$ExpectedPersistenceFingerprint)
    $check=Test-CustomAppProductionPreApplyPreparedResultV010 -Result $PreparedResult;if(-not [bool]$check.ok){return [pscustomobject]@{ok=$false;reason=('generic-prepared-invalid:'+[string]$check.reason)}}
    $pairs=@(
        @('name',$Name),@('consumption_id',$ConsumptionId),@('source_identity',$SourceIdentity),@('remote_commit_sha',$RemoteCommitSha),@('stage_result_fingerprint',$StageResultFingerprint),@('preparation_fingerprint',$PreparationFingerprint),
        @('stage_workspace_path',$StageWorkspacePath),@('stage_path',$StagePath),@('live_tree_sha256',$ExpectedLiveRuntimeTreeSha256),@('stage_tree_sha256',$ExpectedStageRuntimeTreeSha256),@('app_backup_path',$AppBackupPath),@('app_backup_tree_sha256',$ExpectedAppBackupTreeSha256),@('persistence_backup_path',$PersistenceBackupPath),@('persistence_fingerprint',$ExpectedPersistenceFingerprint)
    )
    foreach($p in $pairs){$f=[string]$p[0];$a=[string]$PreparedResult.$f;$b=[string]$p[1];if($f -like '*_path'){try{$a=[IO.Path]::GetFullPath($a).TrimEnd([IO.Path]::DirectorySeparatorChar,[IO.Path]::AltDirectorySeparatorChar);$b=[IO.Path]::GetFullPath($b).TrimEnd([IO.Path]::DirectorySeparatorChar,[IO.Path]::AltDirectorySeparatorChar)}catch{return [pscustomobject]@{ok=$false;reason=('generic-prepared-path-invalid-'+$f)}};if(-not $a.Equals($b,[StringComparison]::OrdinalIgnoreCase)){return [pscustomobject]@{ok=$false;reason=('generic-prepared-continuity-drift-'+$f)}}}elseif($a.Trim().ToLowerInvariant() -cne $b.Trim().ToLowerInvariant()){return [pscustomobject]@{ok=$false;reason=('generic-prepared-continuity-drift-'+$f)}}}
    try{if([int]$PreparedResult.app_backup_file_count -ne $ExpectedAppBackupFileCount -or [int64]$PreparedResult.app_backup_total_bytes -ne $ExpectedAppBackupTotalBytes){return [pscustomobject]@{ok=$false;reason='generic-prepared-backup-count-drift'}}}catch{return [pscustomobject]@{ok=$false;reason='generic-prepared-backup-count-invalid'}}
    return [pscustomobject]@{ok=$true;reason='generic-prepared-continuity-exact'}
}
function Invoke-CustomAppProductionEvidenceBoundJournalAtomicMutationV010 {
    param(
        [Parameter(Mandatory=$true)]$GenericPreparedResult,
        [Parameter(Mandatory=$true)][string]$Name,[Parameter(Mandatory=$true)][string]$CallerAdmissionManagedBy,[Parameter(Mandatory=$true)][string]$CallerAdmissionFingerprint,
        [Parameter(Mandatory=$true)][string]$AllowedRoot,[Parameter(Mandatory=$true)][string]$JournalStoreDirectory,[Parameter(Mandatory=$true)][string]$TransactionNonce,
        [Parameter(Mandatory=$true)][string]$ConsumptionId,[Parameter(Mandatory=$true)][string]$SourceIdentity,[Parameter(Mandatory=$true)][string]$RemoteCommitSha,[Parameter(Mandatory=$true)][string]$StageResultFingerprint,[Parameter(Mandatory=$true)][string]$PreparationFingerprint,[Parameter(Mandatory=$true)][string]$StageWorkspacePath,
        [Parameter(Mandatory=$true)][string]$LivePath,[Parameter(Mandatory=$true)][string]$StagePath,
        [Parameter(Mandatory=$true)][string]$ExpectedLiveRuntimeTreeSha256,[Parameter(Mandatory=$true)][string]$ExpectedLiveFullTreeSha256,[Parameter(Mandatory=$true)][int]$ExpectedLiveFullFileCount,[Parameter(Mandatory=$true)][int64]$ExpectedLiveFullTotalBytes,
        [Parameter(Mandatory=$true)][string]$ExpectedStageRuntimeTreeSha256,[Parameter(Mandatory=$true)][string]$AppBackupPath,[Parameter(Mandatory=$true)][string]$ExpectedAppBackupTreeSha256,[Parameter(Mandatory=$true)][int]$ExpectedAppBackupFileCount,[Parameter(Mandatory=$true)][int64]$ExpectedAppBackupTotalBytes,
        [Parameter(Mandatory=$true)][string]$PersistenceBackupPath,[Parameter(Mandatory=$true)][string]$ExpectedPersistenceFingerprint,[Parameter(Mandatory=$true)][string]$LocalAppDataRoot,[Parameter(Mandatory=$true)][string]$AppDataRoot,
        [DateTimeOffset]$Now=[DateTimeOffset]::UtcNow
    )
    $deny={param([string]$Reason,[string]$Txn=$null,[string]$Phase=$null,[bool]$Started=$false,[bool]$Evidence=$false) New-CustomAppProductionEvidenceBoundJournalAtomicDeniedV010 -Reason $Reason -TransactionRoot $Txn -JournalPhase $Phase -LiveMoveStarted $Started -EvidencePersisted $Evidence}
    if([string]::IsNullOrWhiteSpace($Name) -or [string]::IsNullOrWhiteSpace($CallerAdmissionManagedBy) -or $CallerAdmissionFingerprint -notmatch '^[0-9a-fA-F]{64}$'){return & $deny 'evidence-bound-atomic-caller-admission-invalid'}
    $continuity=Test-CustomAppProductionEvidenceBoundJournalAtomicPreparedContinuityV010 -PreparedResult $GenericPreparedResult -Name $Name -ConsumptionId $ConsumptionId -SourceIdentity $SourceIdentity -RemoteCommitSha $RemoteCommitSha -StageResultFingerprint $StageResultFingerprint -PreparationFingerprint $PreparationFingerprint -StageWorkspacePath $StageWorkspacePath -StagePath $StagePath -ExpectedLiveRuntimeTreeSha256 $ExpectedLiveRuntimeTreeSha256 -ExpectedStageRuntimeTreeSha256 $ExpectedStageRuntimeTreeSha256 -AppBackupPath $AppBackupPath -ExpectedAppBackupTreeSha256 $ExpectedAppBackupTreeSha256 -ExpectedAppBackupFileCount $ExpectedAppBackupFileCount -ExpectedAppBackupTotalBytes $ExpectedAppBackupTotalBytes -PersistenceBackupPath $PersistenceBackupPath -ExpectedPersistenceFingerprint $ExpectedPersistenceFingerprint
    if(-not [bool]$continuity.ok){return & $deny ('evidence-bound-atomic-prepared-denied:'+[string]$continuity.reason)}
    try{$pre=Assert-CustomAppProductionJournalAwareAtomicPreconditionsV010 -Name $Name -LivePath $LivePath -StagePath $StagePath -ExpectedLiveRuntimeTreeSha256 $ExpectedLiveRuntimeTreeSha256 -ExpectedLiveFullTreeSha256 $ExpectedLiveFullTreeSha256 -ExpectedLiveFullFileCount $ExpectedLiveFullFileCount -ExpectedLiveFullTotalBytes $ExpectedLiveFullTotalBytes -ExpectedStageRuntimeTreeSha256 $ExpectedStageRuntimeTreeSha256 -AppBackupPath $AppBackupPath -ExpectedAppBackupTreeSha256 $ExpectedAppBackupTreeSha256 -ExpectedAppBackupFileCount $ExpectedAppBackupFileCount -ExpectedAppBackupTotalBytes $ExpectedAppBackupTotalBytes -PersistenceBackupPath $PersistenceBackupPath -ExpectedPersistenceFingerprint $ExpectedPersistenceFingerprint -LocalAppDataRoot $LocalAppDataRoot -AppDataRoot $AppDataRoot}catch{return & $deny ('evidence-bound-atomic-precondition-denied:'+[string]$_.Exception.Message)}
    $txn=Get-CustomAppProductionJournalAwareAtomicTransactionRootV010 -LivePath $pre.live -TransactionNonce $TransactionNonce;$parent=[IO.Path]::GetDirectoryName($pre.live)
    if(-not ([IO.Path]::GetDirectoryName($txn)).Equals($parent,[StringComparison]::OrdinalIgnoreCase) -or (Test-Path -LiteralPath $txn)){return & $deny 'evidence-bound-atomic-transaction-root-invalid-or-collision' $txn}
    try{
        $identity=New-CustomAppProductionCrashJournalIdentityV010 -Name $Name -ConsumptionId $ConsumptionId -SourceIdentity $SourceIdentity -RemoteCommitSha $RemoteCommitSha -StageResultFingerprint $StageResultFingerprint -PreparationFingerprint $PreparationFingerprint -AllowedRoot $AllowedRoot -LivePath $pre.live -TransactionRoot $txn -StageWorkspacePath $StageWorkspacePath -AppBackupPath $AppBackupPath -PersistenceBackupPath $PersistenceBackupPath
        $init=Initialize-CustomAppProductionCrashJournalV010 -AllowedRoot $AllowedRoot -StoreDirectory $JournalStoreDirectory -Identity $identity -Now $Now
        if($null -eq $init -or -not [bool]$init.ok -or -not [bool]$init.read_after_write_verified){return & $deny ('evidence-bound-atomic-journal-init-denied:'+[string]$init.reason) $txn}
    }catch{return & $deny ('evidence-bound-atomic-journal-init-threw:'+[string]$_.Exception.Message) $txn}
    $phase='prepared';$evidence=$null
    try{
        $evidence=Write-CustomAppProductionRecoveryEvidenceV010 -AllowedRoot $AllowedRoot -StoreDirectory $JournalStoreDirectory -PreparedResult $GenericPreparedResult -Now $Now.AddMilliseconds(1)
        if($null -eq $evidence -or -not [bool]$evidence.ok -or -not [bool]$evidence.persisted -or -not [bool]$evidence.read_after_write_verified){return & $deny ('evidence-bound-atomic-recovery-evidence-denied:'+[string]$evidence.reason) $txn $phase $false}
        if(([string]$evidence.transaction_id).Trim().ToLowerInvariant() -cne ([string]$init.transaction_id).Trim().ToLowerInvariant() -or ([string]$evidence.preparation_fingerprint).Trim().ToLowerInvariant() -cne $PreparationFingerprint.Trim().ToLowerInvariant()){return & $deny 'evidence-bound-atomic-recovery-evidence-continuity-drift' $txn $phase $false $true}
        $evidenceReload=Read-CustomAppProductionRecoveryEvidenceV010 -AllowedRoot $AllowedRoot -StoreDirectory $JournalStoreDirectory -ExpectedTransactionId ([string]$init.transaction_id)
        if($null -eq $evidenceReload -or -not [bool]$evidenceReload.ok -or ([string]$evidenceReload.evidence_fingerprint).Trim().ToLowerInvariant() -cne ([string]$evidence.evidence_fingerprint).Trim().ToLowerInvariant()){return & $deny ('evidence-bound-atomic-recovery-evidence-readback-denied:'+[string]$evidenceReload.reason) $txn $phase $false $true}
        Invoke-CustomAppProductionEvidenceBoundJournalAtomicValidationHookV010 -Checkpoint 'after-recovery-evidence-before-candidate-preparation' -Context ([pscustomobject]@{transaction_root=$txn;live_path=$pre.live;journal_store=$JournalStoreDirectory;evidence=$evidenceReload})
    }catch{return & $deny ('evidence-bound-atomic-recovery-evidence-threw:'+[string]$_.Exception.Message) $txn $phase $false ($null -ne $evidence -and [bool]$evidence.ok)}
    $candidate=Join-Path $txn 'candidate';$old=Join-Path $txn 'old-live'
    try{
        [IO.Directory]::CreateDirectory($txn)|Out-Null;[void](Copy-CustomAppAtomicTreeV010 -Source $pre.stage -Destination $candidate)
        $git=Get-CustomAppAtomicGitSnapshotV010 -LivePath $pre.live;if([bool]$git.present){[void](Copy-CustomAppAtomicTreeV010 -Source (Join-Path $pre.live '.git') -Destination (Join-Path $candidate '.git'))}
        $candidateRuntime=Get-CustomAppLocalRuntimeBaseline -Name $Name -AppPath $candidate
        if(-not [bool]$candidateRuntime.safe -or -not [bool]$candidateRuntime.installable -or (Test-CustomAppLocalRuntimeBaselineMutationAuthority $candidateRuntime) -or ([string]$candidateRuntime.tree_sha256).Trim().ToLowerInvariant() -cne $ExpectedStageRuntimeTreeSha256.Trim().ToLowerInvariant()){throw 'candidate-runtime-verification-failed'}
        $candidateGit=Test-CustomAppAtomicGitSnapshotV010 -LivePath $candidate -Expected $git;if(-not [bool]$candidateGit.ok){throw ('candidate-'+[string]$candidateGit.reason)}
    }catch{return & $deny ('evidence-bound-atomic-candidate-preparation-failed:'+[string]$_.Exception.Message) $txn $phase $false $true}
    $current=$init;$liveMoveStarted=$false
    try{
        $current=Append-CustomAppProductionCrashJournalPhaseV010 -AllowedRoot $AllowedRoot -StoreDirectory $JournalStoreDirectory -ExpectedRevision ([int64]$current.revision) -ExpectedEntrySha256 ([string]$current.entry.entry_sha256) -Phase 'atomic-mutation-starting' -Now $Now.AddSeconds(1)
        if($null -eq $current -or -not [bool]$current.ok -or -not [bool]$current.read_after_write_verified){return & $deny ('evidence-bound-atomic-start-barrier-denied:'+[string]$current.reason) $txn $phase $false $true};$phase='atomic-mutation-starting'
        Invoke-CustomAppProductionEvidenceBoundJournalAtomicValidationHookV010 -Checkpoint 'after-atomic-starting-before-live-move' -Context ([pscustomobject]@{live_path=$pre.live;transaction_root=$txn;candidate_path=$candidate;old_live_path=$old;journal_store=$JournalStoreDirectory})
        [void](Assert-CustomAppProductionJournalAwareAtomicPreconditionsV010 -Name $Name -LivePath $pre.live -StagePath $pre.stage -ExpectedLiveRuntimeTreeSha256 $ExpectedLiveRuntimeTreeSha256 -ExpectedLiveFullTreeSha256 $ExpectedLiveFullTreeSha256 -ExpectedLiveFullFileCount $ExpectedLiveFullFileCount -ExpectedLiveFullTotalBytes $ExpectedLiveFullTotalBytes -ExpectedStageRuntimeTreeSha256 $ExpectedStageRuntimeTreeSha256 -AppBackupPath $AppBackupPath -ExpectedAppBackupTreeSha256 $ExpectedAppBackupTreeSha256 -ExpectedAppBackupFileCount $ExpectedAppBackupFileCount -ExpectedAppBackupTotalBytes $ExpectedAppBackupTotalBytes -PersistenceBackupPath $PersistenceBackupPath -ExpectedPersistenceFingerprint $ExpectedPersistenceFingerprint -LocalAppDataRoot $LocalAppDataRoot -AppDataRoot $AppDataRoot)
        [IO.Directory]::Move($pre.live,$old);$liveMoveStarted=$true
        Invoke-CustomAppProductionEvidenceBoundJournalAtomicValidationHookV010 -Checkpoint 'after-live-move-before-journal' -Context ([pscustomobject]@{live_path=$pre.live;transaction_root=$txn;candidate_path=$candidate;old_live_path=$old;journal_store=$JournalStoreDirectory})
        $current=Append-CustomAppProductionCrashJournalPhaseV010 -AllowedRoot $AllowedRoot -StoreDirectory $JournalStoreDirectory -ExpectedRevision ([int64]$current.revision) -ExpectedEntrySha256 ([string]$current.entry.entry_sha256) -Phase 'live-moved-to-old' -Now $Now.AddSeconds(2)
        if($null -eq $current -or -not [bool]$current.ok -or -not [bool]$current.read_after_write_verified){return & $deny ('evidence-bound-atomic-live-moved-barrier-denied:'+[string]$current.reason) $txn $phase $true $true};$phase='live-moved-to-old'
        Invoke-CustomAppProductionEvidenceBoundJournalAtomicValidationHookV010 -Checkpoint 'after-live-moved-before-candidate' -Context ([pscustomobject]@{live_path=$pre.live;transaction_root=$txn;candidate_path=$candidate;old_live_path=$old;journal_store=$JournalStoreDirectory})
        $oldSnap=Get-CustomAppUpdateTreeSnapshotV010 -Root $old;if(([string]$oldSnap.tree_sha256).Trim().ToLowerInvariant() -cne $ExpectedLiveFullTreeSha256.Trim().ToLowerInvariant() -or [int]$oldSnap.file_count -ne $ExpectedLiveFullFileCount -or [int64]$oldSnap.total_bytes -ne $ExpectedLiveFullTotalBytes){return & $deny 'evidence-bound-atomic-old-live-drift-before-candidate' $txn $phase $true $true}
        $persistMid=Get-SpotifyPersistenceSnapshot -LocalAppDataRoot $LocalAppDataRoot -AppDataRoot $AppDataRoot;if(([string]$persistMid.fingerprint).Trim().ToLowerInvariant() -cne $ExpectedPersistenceFingerprint.Trim().ToLowerInvariant()){return & $deny 'evidence-bound-atomic-persistence-drift-before-candidate' $txn $phase $true $true}
        [IO.Directory]::Move($candidate,$pre.live)
        Invoke-CustomAppProductionEvidenceBoundJournalAtomicValidationHookV010 -Checkpoint 'after-candidate-move-before-journal' -Context ([pscustomobject]@{live_path=$pre.live;transaction_root=$txn;candidate_path=$candidate;old_live_path=$old;journal_store=$JournalStoreDirectory})
        $current=Append-CustomAppProductionCrashJournalPhaseV010 -AllowedRoot $AllowedRoot -StoreDirectory $JournalStoreDirectory -ExpectedRevision ([int64]$current.revision) -ExpectedEntrySha256 ([string]$current.entry.entry_sha256) -Phase 'candidate-live' -Now $Now.AddSeconds(3)
        if($null -eq $current -or -not [bool]$current.ok -or -not [bool]$current.read_after_write_verified){return & $deny ('evidence-bound-atomic-candidate-live-barrier-denied:'+[string]$current.reason) $txn $phase $true $true};$phase='candidate-live'
    }catch{return & $deny ('evidence-bound-atomic-transition-threw:'+[string]$_.Exception.Message) $txn $phase $liveMoveStarted $true}
    try{
        $post=Get-CustomAppLocalRuntimeBaseline -Name $Name -AppPath $pre.live;if(-not [bool]$post.safe -or -not [bool]$post.installable -or ([string]$post.tree_sha256).Trim().ToLowerInvariant() -cne $ExpectedStageRuntimeTreeSha256.Trim().ToLowerInvariant()){return & $deny 'evidence-bound-atomic-post-runtime-mismatch' $txn $phase $true $true}
        $postGit=Test-CustomAppAtomicGitSnapshotV010 -LivePath $pre.live -Expected $git;if(-not [bool]$postGit.ok){return & $deny ('evidence-bound-atomic-post-git-mismatch:'+[string]$postGit.reason) $txn $phase $true $true}
        $persistAfter=Get-SpotifyPersistenceSnapshot -LocalAppDataRoot $LocalAppDataRoot -AppDataRoot $AppDataRoot;if(([string]$persistAfter.fingerprint).Trim().ToLowerInvariant() -cne $ExpectedPersistenceFingerprint.Trim().ToLowerInvariant()){return & $deny 'evidence-bound-atomic-post-persistence-drift' $txn $phase $true $true}
        $evidenceAfter=Read-CustomAppProductionRecoveryEvidenceV010 -AllowedRoot $AllowedRoot -StoreDirectory $JournalStoreDirectory -ExpectedTransactionId ([string]$current.transaction_id);if($null -eq $evidenceAfter -or -not [bool]$evidenceAfter.ok -or ([string]$evidenceAfter.evidence_fingerprint).Trim().ToLowerInvariant() -cne ([string]$evidence.evidence_fingerprint).Trim().ToLowerInvariant()){return & $deny ('evidence-bound-atomic-post-evidence-reload-denied:'+[string]$evidenceAfter.reason) $txn $phase $true $true}
        $r=[pscustomobject]@{
            schema=1;managed_by=$CustomAppProductionEvidenceBoundJournalAtomicManagedBy;qualified_journal_aware_head=$CustomAppProductionEvidenceBoundJournalAtomicQualifiedJournalAwareHead;qualified_journal_aware_core_blob=$CustomAppProductionEvidenceBoundJournalAtomicQualifiedJournalAwareCoreBlob;qualified_recovery_evidence_head=$CustomAppProductionEvidenceBoundJournalAtomicQualifiedEvidenceHead;qualified_recovery_evidence_core_blob=$CustomAppProductionEvidenceBoundJournalAtomicQualifiedEvidenceCoreBlob
            name=$Name;transaction_id=([string]$current.transaction_id).Trim().ToLowerInvariant();transaction_root=$txn;old_live_path=$old;live_path=$pre.live;stage_path=$pre.stage;pre_live_full_tree_sha256=$ExpectedLiveFullTreeSha256.Trim().ToLowerInvariant();post_runtime_tree_sha256=([string]$post.tree_sha256).Trim().ToLowerInvariant();persistence_fingerprint=([string]$persistAfter.fingerprint).Trim().ToLowerInvariant();journal_revision=[int64]$current.revision;journal_entry_sha256=([string]$current.entry.entry_sha256).Trim().ToLowerInvariant();recovery_evidence_fingerprint=([string]$evidenceAfter.evidence_fingerprint).Trim().ToLowerInvariant();recovery_evidence_path=[string]$evidenceAfter.path;recovery_evidence_persisted=$true;recovery_evidence_bound_before_atomic_barrier=$true
            live_code_swap_performed=$true;requires_transaction_finalization=$true;requires_spicetify_apply_phase=$true;result_is_authority=$false;spicetify_apply_authorized=$false;additional_mutation_authorized=$false;production_execution_authorized=$false;production_mutation_authorized=$false;result_fingerprint=$null
        }
        $r.result_fingerprint=Get-CustomAppProductionEvidenceBoundJournalAtomicSha256V010 (Get-CustomAppProductionEvidenceBoundJournalAtomicResultMaterialV010 -Result $r)
        $rc=Test-CustomAppProductionEvidenceBoundJournalAtomicResultV010 -Result $r;if(-not [bool]$rc.ok){return & $deny ('evidence-bound-atomic-output-invalid:'+[string]$rc.reason) $txn $phase $true $true}
        return [pscustomobject]@{ok=$true;reason='evidence-bound-journal-atomic-candidate-live-durable-zero-future-authority';result=$r;recovery_evidence_persisted=$true;recovery_evidence_bound_before_atomic_barrier=$true;live_code_swap_performed=$true;result_is_authority=$false;spicetify_apply_authorized=$false;additional_mutation_authorized=$false;production_execution_authorized=$false;production_mutation_authorized=$false}
    }catch{return & $deny ('evidence-bound-atomic-post-verification-threw:'+[string]$_.Exception.Message) $txn $phase $true $true}
}
